"""Optional Home Screen launchers for installed TOLF shortcuts.

This module contains no account data and does not guess iOS-local VPN IDs.
"""
import base64
import uuid
from urllib.parse import quote

ICONS = {'on': '', 'off': ''}


def webclip_payloads(device_id):
    payloads = []
    for mode in ("on", "off"):
        name = "TOLF " + mode.upper()
        identifier = "is.tolf.anyconnect.launcher." + str(device_id) + "." + mode
        payloads.append({
            "PayloadType": "com.apple.webClip.managed",
            "PayloadVersion": 1,
            "PayloadIdentifier": identifier,
            "PayloadUUID": str(uuid.uuid5(uuid.NAMESPACE_URL, identifier)).upper(),
            "PayloadDisplayName": name,
            "Label": name,
            "URL": "shortcuts://run-shortcut?name=TOLF&input=text&text=" + mode,
            "Icon": base64.b64decode(ICONS[mode]),
            "IsRemovable": True,
            "FullScreen": False,
            "Precomposed": True,
        })
    return payloads
